import { expect } from '@playwright/test';

export class BankHomePage {
  constructor(page) {
    this.page = page;
    this.customerLoginButton = page.getByRole('button', {
      name: 'Customer Login',
    });
    this.managerLoginButton = page.getByRole('button', {
      name: 'Bank Manager Login',
    });
  }

  async open() {
    await this.page.goto('/angularJs-protractor/BankingProject/#/login');
  }

  async clickCustomerLoginButton() {
    await this.customerLoginButton.click();
  }

  async clickManagerLoginButton() {
    await this.managerLoginButton.click();
  }
}

import { expect } from '@playwright/test';

export class AddCustomerPage {
  constructor(page) {
    this.page = page;
    this.firstNameInput = page.getByPlaceholder('First Name');
    this.lastNameInput = page.getByPlaceholder('Last Name');
    this.postCodeInput = page.getByPlaceholder('Post Code');
    this.submitButton = page.getByRole('form').getByRole('button', { name: 'Add Customer' });
  }

  async open() {
    await this.page.goto(
      '/angularJs-protractor/BankingProject/#/manager/addCust',
    );
  }

  async fillFirstName(firstName) {
    await this.firstNameInput.fill(firstName);
  }

  async fillLastName(lastName) {
    await this.lastNameInput.fill(lastName);
  }

  async fillPostCode(postCode) {
    await this.postCodeInput.fill(postCode);
  }

  async clickSubmit() {
    await this.submitButton.click();
  }
}

import { expect } from '@playwright/test';

export class BankManagerMainPage {
  constructor(page) {
    this.page = page;
    this.addCustomerButton = page.getByRole('button', { name: 'Add Customer' });
    this.openAccountButton = page.getByRole('button', { name: 'Open Account' });
    this.customersButton = page.getByRole('button', { name: 'Customers' });
  }

  async open() {
    await this.page.goto('/angularJs-protractor/BankingProject/#/manager');
  }

  async clickAddCustomer() {
    await this.addCustomerButton.click();
  }

  async clickOpenAccount() {
    await this.openAccountButton.click();
  }

  async clickCustomers() {
    await this.customersButton.click();
  }
}

import { expect } from '@playwright/test';

export class CustomersListPage {
  constructor(page) {
    this.page = page;
    this.searchInput = page.getByPlaceholder('Search Customer');
    this.customerRows = page.locator('table tbody tr');
  }

  async open() {
    await this.page.goto('/angularJs-protractor/BankingProject/#/manager/list');
  }

  async searchCustomer(searchText) {
    await this.searchInput.fill(searchText);
  }

  async getCustomerRow(index) {
    return this.customerRows.nth(index);
  }

  async getLastCustomerRow() {
    return this.customerRows.last();
  }

  async getCustomerRowByFirstName(firstName) {
    return this.customerRows.filter({ hasText: firstName });
  }

  async getDeleteButtonForRow(row) {
    return row.getByRole('button', { name: 'Delete' });
  }

  async getRowsCount() {
    return await this.customerRows.count();
  }
}

import { expect } from '@playwright/test';

export class OpenAccountPage {
  constructor(page) {
    this.page = page;
    this.customerSelect = page.locator('#userSelect');
    this.currencySelect = page.locator('#currency');
    this.processButton = page.getByRole('button', { name: 'Process' });
  }

  async open() {
    await this.page.goto(
      '/angularJs-protractor/BankingProject/#/manager/openAccount',
    );
  }

  async selectCustomer(customerName) {
    await this.customerSelect.selectOption({ label: customerName });
  }

  async selectCurrency(currency) {
    await this.currencySelect.selectOption(currency);
  }

  async getSelectedCurrency() {
    const selectedValue = await this.currencySelect.inputValue();
    return selectedValue;
  }

  async clickProcess() {
    await this.processButton.click();
  }
}

import { test, expect } from '@playwright/test';
import { faker } from '@faker-js/faker';
import { AddCustomerPage } from '../../../src/pages/manager/AddCustomerPage.js';
import { BankManagerMainPage } from '../../../src/pages/manager/BankManagerMainPage.js';
import { CustomersListPage } from '../../../src/pages/manager/CustomersListPage.js';

test('Assert manager can add new customer', async ({ page }) => {
  const addCustomerPage = new AddCustomerPage(page);
  const managerMainPage = new BankManagerMainPage(page);
  const customersListPage = new CustomersListPage(page);

  const firstName = faker.person.firstName();
  const lastName = faker.person.lastName();
  const postCode = faker.location.zipCode(); 

  await addCustomerPage.open();
  await addCustomerPage.fillFirstName(firstName);
  await addCustomerPage.fillLastName(lastName);
  await addCustomerPage.fillPostCode(postCode);

  // Accept dialog popup after adding customer
  page.once('dialog', dialog => dialog.accept());
  await addCustomerPage.clickSubmit();

  await page.reload();

  await managerMainPage.clickCustomers();

  const lastRow = await customersListPage.getLastCustomerRow();

  await expect(lastRow.locator('td').nth(0)).toHaveText(firstName);
  await expect(lastRow.locator('td').nth(1)).toHaveText(lastName);
  await expect(lastRow.locator('td').nth(2)).toHaveText(postCode);
  await expect(lastRow.locator('td').nth(3)).toBeEmpty();
});

import { test, expect } from '@playwright/test';
import { BankHomePage } from '../../../src/pages/BankHomePage.js';
import { BankManagerMainPage } from '../../../src/pages/manager/BankManagerMainPage.js';

test('Assert manager can Login', async ({ page }) => {
  const bankHomePage = new BankHomePage(page);
  const managerMainPage = new BankManagerMainPage(page);

  await bankHomePage.open();
  await bankHomePage.clickManagerLoginButton();

  await expect(managerMainPage.addCustomerButton).toBeVisible();
  await expect(managerMainPage.openAccountButton).toBeVisible();
  await expect(managerMainPage.customersButton).toBeVisible();
});

import { test, expect } from '@playwright/test';
import { faker } from '@faker-js/faker';
import { AddCustomerPage } from '../../../src/pages/manager/AddCustomerPage.js';
import { CustomersListPage } from '../../../src/pages/manager/CustomersListPage.js';

let firstName;
let lastName;
let postalCode;

test.beforeEach(async ({ page }) => {
  const addCustomerPage = new AddCustomerPage(page);
  firstName = faker.person.firstName();
  lastName = faker.person.lastName();
  postalCode = faker.location.zipCode();

  await addCustomerPage.open();
  await addCustomerPage.fillFirstName(firstName);
  await addCustomerPage.fillLastName(lastName);
  await addCustomerPage.fillPostCode(postalCode);

  page.once('dialog', dialog => dialog.accept());
  await addCustomerPage.clickSubmit();
});

test('Assert manager can delete customer', async ({ page }) => {
  const customersListPage = new CustomersListPage(page);
  await customersListPage.open();

  await customersListPage.searchCustomer(firstName);
  await expect(customersListPage.customerRows).toHaveCount(1);

  const row = await customersListPage.getCustomerRow(0);
  const deleteBtn = await customersListPage.getDeleteButtonForRow(row);
  await deleteBtn.click();

  await expect(customersListPage.customerRows).toHaveCount(0);

  await page.reload();
  await customersListPage.searchCustomer(firstName);
  await expect(customersListPage.customerRows).toHaveCount(0);
});

import { test, expect } from '@playwright/test';
